/**
 * Registers a handler for one event type. Call the return value to detach.
 *
 * The handler set is copy-on-write: a subscribe that happens while `emit()` is
 * walking the set (a handler that attaches another handler) never mutates the
 * collection being iterated.
 */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set: HandlerSet = new Set(handlers.get(type));
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

input.new_string:
/**
 * Registers a handler for one event type. Call the return value to detach.
 *
 * The handler set is copy-on-write: a subscribe that happens while `emit()` is
 * walking the set (a handler that attaches another handler) never mutates the
 * collection being iterated. Detach edits the set currently stored for the
 * event. Deleting from the set captured at subscribe time would leave the
 * handler attached once a later subscribe had replaced that set, so a
 * detach/attach cycle would stack a second copy of every earlier listener.
 */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set: HandlerSet = new Set(handlers.get(type));
  const fn = handler as EventHandler<TaskflowEventType>;
  set.add(fn);
  handlers.set(type, set);
  return () => {
    const current = handlers.get(type);
    if (!current?.has(fn)) return;
    const next: HandlerSet = new Set(current);
    next.delete(fn);
    if (next.size === 0) handlers.delete(type);
    else handlers.set(type, next);
  };
}

