import { afterAll, describe, expect, it } from "vitest";
import { resetEventBus, subscriberCount } from "@/lib/event-bus";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";

describe("event handler rewire", () => {
  afterAll(() => {
    unregisterEventHandlers();
    resetEventBus();
  });

  it("stays single-delivery across detach and reattach", () => {
    registerEventHandlers();
    registerEventHandlers();

    const attached = {
      created: subscriberCount("issue.created"),
      status: subscriberCount("issue.status_changed"),
      assigned: subscriberCount("issue.assigned"),
      digest: subscriberCount("digest.due"),
    };

    expect(attached.created).toBeGreaterThan(0);
    expect(attached.digest).toBe(1);

    unregisterEventHandlers();
    expect(subscriberCount("issue.created")).toBe(0);
    expect(subscriberCount("issue.status_changed")).toBe(0);
    expect(subscriberCount("digest.due")).toBe(0);
    const assignedWhileDetached = subscriberCount("issue.assigned");
    const commentWhileDetached = subscriberCount("comment.created");

    for (let i = 0; i < 3; i++) {
      registerEventHandlers();
      unregisterEventHandlers();
    }
    registerEventHandlers();
    registerEventHandlers();

    expect(subscriberCount("issue.created")).toBe(attached.created);
    expect(subscriberCount("issue.status_changed")).toBe(attached.status);
    expect(subscriberCount("issue.assigned")).toBe(attached.assigned);
    expect(subscriberCount("digest.due")).toBe(1);

    unregisterEventHandlers();
    expect(subscriberCount("issue.assigned")).toBe(assignedWhileDetached);
    expect(subscriberCount("comment.created")).toBe(commentWhileDetached);
    expect(assignedWhileDetached).toBeGreaterThan(0);
    expect(commentWhileDetached).toBeGreaterThan(0);
  });
});

